mapper.select:
SELECT v.orderid AS orderId, v.customername AS customerName, v.salesrepname AS salesRepName, v.orderdate AS orderDate, v.status AS status, v.itemcount AS itemCount, v.subtotal AS subtotal, v.shippingfee AS shippingFee, v.totalamount AS totalAmount FROM v_orderSummary v
JOIN orders o ON o.orderid = v.orderid
ORDER BY v.orderdate DESC LIMIT #{limit} OFFSET #{offset}
